import hashlib,json,os,pathlib,re,subprocess
root=pathlib.Path("/home/admin1/projects/TGserver")
logs=pathlib.Path("/home/admin1/logs/TGserver")
print("ACTION=TGZERO_HISTORY_DISCOVERY_READ_ONLY")
try: print("TGS_HEAD="+subprocess.check_output(["git","-C",str(root),"rev-parse","HEAD"],text=True,timeout=5).strip())
except Exception: print("TGS_HEAD=UNKNOWN")
live=root/".tgs-state/topics.json"
try:
    obj=json.loads(live.read_text())
    print("LIVE_PROJECTS="+str(len(obj))+" LIVE_ROUTES="+str(sum(len(v) for v in obj.values() if isinstance(v,dict))))
except Exception as e: print("LIVE_STATE=ERROR_"+type(e).__name__)
checkpoint=logs/"deployments/20261007-p014/EXECUTION_CHECKPOINT.json"
try:
    if checkpoint.is_symlink() or not checkpoint.is_file(): raise ValueError("NOT_REGULAR")
    raw=checkpoint.read_bytes()
    cp=json.loads(raw)
    print("OCT07_CHECKPOINT=READABLE sha16="+hashlib.sha256(raw).hexdigest()[:16]+" bytes="+str(len(raw)))
    if isinstance(cp,dict):
        print("OCT07_TOP_KEYS="+",".join(sorted(str(k) for k in cp.keys())[:20]))
        for k,v in cp.items():
            if isinstance(v,(list,dict)) and re.search("topic|route|state|map|deploy|result|project",str(k),re.I):
                print("OCT07_FIELD_"+str(k)[:30]+"="+str(len(v)))
except Exception as e: print("OCT07_CHECKPOINT=ERROR_"+type(e).__name__)
found=[]
visited=0
for base in (root/".tgs-state",logs):
    if not base.is_dir(): continue
    for dirname,dirs,files in os.walk(base,followlinks=False):
        dirs[:]=sorted(d for d in dirs if not (pathlib.Path(dirname)/d).is_symlink() and len(pathlib.Path(dirname,d).relative_to(base).parts)<=5)
        for name in sorted(files):
            visited+=1
            if visited>10000: break
            p=pathlib.Path(dirname)/name
            if not p.is_symlink() and p.suffix==".json" and re.search(r"topic|backup|2026100[478]|2026-10-0[478]|state",str(p),re.I):
                found.append((base,p))
        if visited>10000: break
print("SCAN_FILES="+str(visited)+" CANDIDATES="+str(len(found)))
for i,(base,p) in enumerate(found[:28]):
    try:
        raw=p.read_bytes() if p.stat().st_size<=5000000 else None
        if raw is None: print("CANDIDATE_"+str(i+1)+"=OVERSIZE"); continue
        j=json.loads(raw)
        if isinstance(j,dict):
            k=[v for key,v in j.items() if re.fullmatch(r"P[0-9]{3}",str(key)) and isinstance(v,dict)]
            print("CANDIDATE_"+str(i+1)+"="+str(p.relative_to(base))+" sha16="+hashlib.sha256(raw).hexdigest()[:16]+" project_maps="+str(len(k))+" routes="+str(sum(len(v) for v in k))+" topkeys="+",".join(list(map(str,j.keys()))[:3]))
        else: print("CANDIDATE_"+str(i+1)+"="+str(p.relative_to(base))+" sha16="+hashlib.sha256(raw).hexdigest()[:16]+" type="+type(j).__name__)
    except Exception as e: print("CANDIDATE_"+str(i+1)+"=ERROR_"+type(e).__name__)
print("MUTATION=NONE")
GACE_HISTORY_READ_ONLY
